-- Reviewed setup for the FOODPULSE analytical schema.
-- The loader opens a connection without a database or schema, checks the warehouse,
-- then runs the USE and CREATE IF NOT EXISTS statements below.
-- With --tables, only the selected CREATE TABLE statements are executed.
-- Create the virtual warehouse in the Snowflake UI and grant usage before running --execute.
-- This file does not drop, truncate, or replace objects, and it does not create a virtual warehouse.
-- DDL commits on its own. A multi-table load is not one atomic snapshot.

USE WAREHOUSE FOODPULSE_WH;

CREATE DATABASE IF NOT EXISTS FOODPULSE;

CREATE SCHEMA IF NOT EXISTS FOODPULSE.ANALYTICS;

USE DATABASE FOODPULSE;

USE SCHEMA ANALYTICS;

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.REVIEW_SENTIMENT (REVIEW_ID VARCHAR, OVERALL_SENTIMENT VARCHAR, OVERALL_SCORE FLOAT, FOOD_SENT VARCHAR, SERVICE_SENT VARCHAR, AMBIENCE_SENT VARCHAR, PRICE_SENT VARCHAR, ANALYZED_AT TIMESTAMP_TZ, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.SENTIMENT_BY_RESTAURANT (RESTAURANT_ID VARCHAR, REVIEW_COUNT NUMBER, POSITIVE_COUNT NUMBER, NEGATIVE_COUNT NUMBER, NEUTRAL_COUNT NUMBER, INVALID_COUNT NUMBER, MEAN_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.SENTIMENT_BY_CITY (CITY VARCHAR, REVIEW_COUNT NUMBER, POSITIVE_COUNT NUMBER, NEGATIVE_COUNT NUMBER, NEUTRAL_COUNT NUMBER, INVALID_COUNT NUMBER, MEAN_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.SENTIMENT_BY_CUISINE (CUISINE_TYPE VARCHAR, REVIEW_COUNT NUMBER, POSITIVE_COUNT NUMBER, NEGATIVE_COUNT NUMBER, NEUTRAL_COUNT NUMBER, INVALID_COUNT NUMBER, MEAN_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.SENTIMENT_BY_MONTH (MONTH VARCHAR, REVIEW_COUNT NUMBER, POSITIVE_COUNT NUMBER, NEGATIVE_COUNT NUMBER, NEUTRAL_COUNT NUMBER, INVALID_COUNT NUMBER, MEAN_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.CUSTOMER_SEGMENTS (CUSTOMER_ID VARCHAR, CLUSTER_ID NUMBER, SEGMENT_LABEL VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.CUSTOMER_SEGMENT_SUMMARY (CLUSTER_ID NUMBER, SEGMENT_LABEL VARCHAR, COUNT NUMBER, PERCENT FLOAT, MEAN_RECENCY_DAYS FLOAT, MEDIAN_RECENCY_DAYS FLOAT, MEAN_ORDER_FREQUENCY FLOAT, MEDIAN_ORDER_FREQUENCY FLOAT, MEAN_TOTAL_SPEND FLOAT, MEDIAN_TOTAL_SPEND FLOAT, MEAN_AVG_ORDER_VALUE FLOAT, MEDIAN_AVG_ORDER_VALUE FLOAT, MEAN_AVG_DISCOUNT FLOAT, MEDIAN_AVG_DISCOUNT FLOAT, MEAN_AVG_RATING FLOAT, MEDIAN_AVG_RATING FLOAT, MEAN_AVG_SENTIMENT_SCORE FLOAT, MEDIAN_AVG_SENTIMENT_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.ASSOCIATION_FREQUENT_ITEMSETS (ITEM_IDS VARCHAR, ITEM_NAMES VARCHAR, ITEMSET_SIZE NUMBER, SUPPORT_COUNT NUMBER, SUPPORT FLOAT, RESTAURANT_SCOPE VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.ASSOCIATION_RULES (ANTECEDENT_IDS VARCHAR, ANTECEDENT_NAMES VARCHAR, CONSEQUENT_IDS VARCHAR, CONSEQUENT_NAMES VARCHAR, SUPPORT_COUNT NUMBER, SUPPORT FLOAT, CONFIDENCE FLOAT, LIFT FLOAT, LEVERAGE FLOAT, CONVICTION FLOAT, RESTAURANT_SCOPE VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.CUSTOMER_CHURN_RISK (CUSTOMER_ID VARCHAR, INACTIVITY_DAYS NUMBER, OBSERVATION_DAYS NUMBER, ORDER_FREQUENCY NUMBER, TOTAL_SPEND FLOAT, AVG_ORDER_VALUE FLOAT, AVG_DISCOUNT FLOAT, DISCOUNT_USAGE_RATE FLOAT, AVG_RATING FLOAT, REVIEW_FREQUENCY NUMBER, AVG_SENTIMENT_SCORE FLOAT, MEAN_PURCHASE_GAP_DAYS FLOAT, PURCHASE_GAP_STD_DAYS FLOAT, RECENT_ORDER_COUNT NUMBER, PRIOR_ORDER_COUNT NUMBER, RISK_SCORE FLOAT, RISK_CATEGORY VARCHAR, REASON_CODES VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.CUSTOMER_CHURN_SUMMARY (RISK_CATEGORY VARCHAR, CUSTOMER_COUNT NUMBER, SHARE FLOAT, MEDIAN_INACTIVITY_DAYS FLOAT, MEDIAN_ORDER_FREQUENCY FLOAT, MEDIAN_TOTAL_SPEND FLOAT, MEDIAN_AVG_ORDER_VALUE FLOAT, MEDIAN_AVG_RATING FLOAT, MEDIAN_AVG_SENTIMENT_SCORE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.FOOD_RECOMMENDATIONS (CUSTOMER_ID VARCHAR, FOOD_ITEM_ID VARCHAR, RESTAURANT_ID VARCHAR, RECOMMENDATION_SCORE FLOAT, RANK NUMBER, REASON VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.RESTAURANT_RECOMMENDATIONS (CUSTOMER_ID VARCHAR, RESTAURANT_ID VARCHAR, RECOMMENDATION_SCORE FLOAT, RANK NUMBER, REASON VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.DEMAND_FORECASTS (LEVEL VARCHAR, RESTAURANT_ID VARCHAR, FOOD_ITEM_ID VARCHAR, FORECAST_DATE TIMESTAMP_TZ, HORIZON_STEP NUMBER, HORIZON NUMBER, AGGREGATION VARCHAR, MODEL_NAME VARCHAR, PREDICTED_DEMAND FLOAT, FORECAST_ROLE VARCHAR, EVALUATION_MAE FLOAT, EVALUATION_RMSE FLOAT, EVALUATION_WAPE FLOAT, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.CUSTOMER_FEATURES (CUSTOMER_ID VARCHAR, RECENCY_DAYS NUMBER, ORDER_FREQUENCY NUMBER, TOTAL_SPEND FLOAT, AVG_ORDER_VALUE FLOAT, AVG_RATING FLOAT, REVIEW_FREQUENCY NUMBER, DISCOUNT_USAGE_RATE FLOAT, FEATURE_REFERENCE_DATE VARCHAR, LOADED_AT TIMESTAMP_TZ);

CREATE TABLE IF NOT EXISTS FOODPULSE.ANALYTICS.RESTAURANT_FEATURES (RESTAURANT_ID VARCHAR, AVG_RATING FLOAT, ROLLING_AVG_RATING FLOAT, REVIEW_VOLUME NUMBER, ORDER_VOLUME NUMBER, COMPLAINT_COUNT NUMBER, SENTIMENT_LABEL VARCHAR, SENTIMENT_SCORE FLOAT, FEATURE_REFERENCE_DATE VARCHAR, LOADED_AT TIMESTAMP_TZ);
